input.sparql:
SELECT ?ts ?p WHERE {
  ?p a brick:ChilledWaterPump .
  FILTER(regex(str(?p),"HWPump01","i"))
  ?p ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
}

SELECT ?p ?cls ?ts WHERE {
  ?p a ?cls .
  FILTER(regex(str(?p),"HWPump01","i"))
  OPTIONAL { ?p ref:hasExternalReference ?ref . ?ref ref:hasTimeseriesId ?ts . }
}
